# O(n) optimized version
def find_duplicates(lst: list) -> list:
    seen = set()           # O(1) average lookup
    duplicates = set()     # dedup automatically, O(1) average insert

    for item in lst:       # single pass: O(n)
        if item in seen:   # O(1) average
            duplicates.add(item)
        else:
            seen.add(item)

    return list(duplicates)

# Alternative: preserve first occurrence order
def find_duplicates_ordered(lst: list) -> list:
    seen = set()
    duplicates = []
    duplicate_set = set()  # track what we've already added to avoid O(n) `in` check

    for item in lst:
        if item in seen and item not in duplicate_set:
            duplicates.append(item)
            duplicate_set.add(item)
        else:
            seen.add(item)

    return duplicates

# Collections.Counter approach - also O(n) but different use case
from collections import Counter

def find_duplicates_counter(lst: list) -> list:
    counts = Counter(lst)  # O(n)
    return [item for item, count in counts.items() if count > 1]  # O(n)

# If you need count info too
def find_duplicates_with_counts(lst: list) -> dict:
    counts = Counter(lst)
    return {item: count for item, count in counts.items() if count > 1}
