import functools
import time
import random
from typing import TypeVar, Callable, Any, Type, Union, Tuple

F = TypeVar('F', bound=Callable[..., Any])

def retry(
    max_attempts: int = 3,
    delay: float = 1.0,
    backoff_factor: float = 2.0,
    jitter: bool = True,
    exceptions: Union[Type[Exception], Tuple[Type[Exception], ...]] = Exception
) -> Callable[[F], F]:
    """
    max_attempts: total attempts (original + retries)
    delay: initial delay in seconds
    backoff_factor: multiplier for exponential backoff  
    jitter: add randomization to prevent thundering herd
    exceptions: exception types to catch and retry on
    """

    if max_attempts < 1:
        raise ValueError("max_attempts must be >= 1")
    if delay < 0:
        raise ValueError("delay must be >= 0") 
    if backoff_factor <= 0:
        raise ValueError("backoff_factor must be > 0")

    def decorator(func: F) -> F:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None

            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e

                    # Don't sleep after final attempt
                    if attempt == max_attempts - 1:
                        break

                    # Calculate delay: base * (backoff_factor ^ attempt)
                    current_delay = delay * (backoff_factor ** attempt)

                    # Add jitter: uniform random between [0.5, 1.5] * calculated_delay
                    if jitter:
                        current_delay *= (0.5 + random.random())

                    time.sleep(current_delay)

            # Re-raise the last exception with original traceback
            raise last_exception

        return wrapper
    return decorator

# Usage examples:
@retry()  # default: 3 attempts, 1s initial delay, 2x backoff
def flaky_api_call():
    import requests
    return requests.get("https://api.example.com/data").json()

@retry(max_attempts=5, delay=0.5, backoff_factor=1.5)
def database_query():
    # Retries: 0.5s, 0.75s, 1.125s, 1.6875s
    pass

@retry(exceptions=(ConnectionError, TimeoutError))  # only retry specific exceptions
def network_operation():
    pass

# Without jitter for deterministic testing:
@retry(max_attempts=3, delay=1.0, jitter=False)
def deterministic_retry():
    pass
```

The core retry logic handles attempt counting correctly (attempt 0 is first try, no sleep after final failure). Exponential backoff uses `delay * (backoff_factor ** attempt)` so delays are: `delay`, `delay * backoff_factor`, `delay * backoff_factor^2`, etc.

Jitter implementation uses uniform distribution `[0.5, 1.5] * calculated_delay` to prevent synchronized retries across multiple clients. The `exceptions` parameter accepts single exception type or tuple for isinstance() compatibility.

The decorator preserves function metadata via `functools.wraps` and maintains original exception traceback by re-raising rather than raising new exception. Type hints ensure static analysis works correctly with decorated functions.

Edge cases handled: zero/negative delays, invalid attempt counts, no sleep after final attempt, proper exception propagation. The random jitter prevents thundering herd problems in distributed systems.

