from typing import Optional, List, TypeVar, Generic
import heapq

T = TypeVar('T')

class PriorityQueue(Generic[T]):
    def __init__(self) -> None:
        self._heap: List[T] = []

    def insert(self, item: T) -> None:
        """O(log n) insertion via upward bubbling"""
        heapq.heappush(self._heap, item)

    def extract_min(self) -> T:
        """O(log n) removal with downward sifting. Raises IndexError if empty."""
        if not self._heap:
            raise IndexError("extract_min from empty priority queue")
        return heapq.heappop(self._heap)

    def peek(self) -> T:
        """O(1) minimum access. Raises IndexError if empty."""
        if not self._heap:
            raise IndexError("peek at empty priority queue")
        return self._heap[0]

    def __len__(self) -> int:
        return len(self._heap)

    def __bool__(self) -> bool:
        return bool(self._heap)

# Custom implementation without heapq for educational purposes
class BinaryHeapPriorityQueue(Generic[T]):
    def __init__(self) -> None:
        self._heap: List[T] = []
        self._size: int = 0

    def _parent(self, i: int) -> int:
        return (i - 1) >> 1  # (i - 1) // 2

    def _left_child(self, i: int) -> int:
        return (i << 1) + 1  # 2 * i + 1

    def _right_child(self, i: int) -> int:
        return (i << 1) + 2  # 2 * i + 2

    def _swap(self, i: int, j: int) -> None:
        self._heap[i], self._heap[j] = self._heap[j], self._heap[i]

    def _bubble_up(self, i: int) -> None:
        """Restore heap property upward from index i"""
        while i > 0:
            parent_idx = self._parent(i)
            if self._heap[i] >= self._heap[parent_idx]:
                break
            self._swap(i, parent_idx)
            i = parent_idx

    def _bubble_down(self, i: int) -> None:
        """Restore heap property downward from index i"""
        while True:
            min_idx = i
            left = self._left_child(i)
            right = self._right_child(i)

            # Find minimum among node and children
            if left < self._size and self._heap[left] < self._heap[min_idx]:
                min_idx = left
            if right < self._size and self._heap[right] < self._heap[min_idx]:
                min_idx = right

            if min_idx == i:  # Heap property satisfied
                break

            self._swap(i, min_idx)
            i = min_idx

    def insert(self, item: T) -> None:
        """O(log n) worst case, O(1) average for random data"""
        if self._size >= len(self._heap):
            self._heap.append(item)
        else:
            self._heap[self._size] = item

        self._bubble_up(self._size)
        self._size += 1

    def extract_min(self) -> T:
        """O(log n) - replace root with last, then sift down"""
        if self._size == 0:
            raise IndexError("extract_min from empty priority queue")

        min_item = self._heap[0]
        self._size -= 1

        if self._size > 0:
            # Move last element to root and restore heap property
            self._heap[0] = self._heap[self._size]
            self._bubble_down(0)

        return min_item

    def peek(self) -> T:
        """O(1) - root is always minimum in min-heap"""
        if self._size == 0:
            raise IndexError("peek at empty priority queue")
        return self._heap[0]

    def __len__(self) -> int:
        return self._size

    def __bool__(self) -> bool:
        return self._size > 0

