from dataclasses import dataclass

@dataclass
class Task:
    priority: int
    name: str

    def __lt__(self, other: 'Task') -> bool:
        return self.priority < other.priority

# Example usage demonstrating edge cases
def test_priority_queue():
    pq = BinaryHeapPriorityQueue[Task]()

    # Empty queue edge cases
    try:
        pq.extract_min()  # Should raise IndexError
        assert False, "Should have raised IndexError"
    except IndexError:
        pass

    try:
        pq.peek()  # Should raise IndexError
        assert False, "Should have raised IndexError"
    except IndexError:
        pass

    # Single element
    pq.insert(Task(5, "medium"))
    assert pq.peek().priority == 5
    assert len(pq) == 1

    # Multiple elements - heap property maintenance
    pq.insert(Task(1, "high"))
    pq.insert(Task(10, "low"))
    pq.insert(Task(3, "med-high"))

    assert pq.peek().priority == 1  # Min should be at root

    # Extract in priority order
    extracted = []
    while pq:
        extracted.append(pq.extract_min().priority)

    assert extracted == [1, 3, 5, 10]  # Should be sorted

# For duplicate priorities, use tuples with tiebreaker
def test_duplicate_priorities():
    pq = PriorityQueue[tuple[int, int]]()  # (priority, insertion_order)

    counter = 0
    for priority in [5, 2, 5, 1, 2]:
        pq.insert((priority, counter))
        counter += 1

    # Extract maintains relative order for equal priorities via counter
    result = []
    while pq:
        result.append(pq.extract_min())

    # Priorities: 1, 2, 2, 5, 5 with insertion order preserved
    assert result == [(1, 3), (2, 1), (2, 4), (5, 0), (5, 2)]
```

The custom implementation explicitly manages the heap invariant: `heap[i] <= heap[2*i+1]` and `heap[i] <= heap[2*i+2]` for all valid indices. The heapq module uses the same underlying array-based binary heap but with optimized C implementation. Both maintain O(log n) for insert/extract_min, O(1) for peek.

Note the bit manipulation for parent/child index calculations - micro-optimization but demonstrates systems thinking. The bubble_up/bubble_down methods are the core heap operations that maintain the min-heap property after modifications.

