import functools
from typing import Any, Callable, Dict, Tuple, TypeVar, Union
from collections.abc import Hashable

F = TypeVar('F', bound=Callable[..., Any])

def memoize(fn: F) -> F:
    cache: Dict[Tuple[Tuple[Any, ...], Tuple[Tuple[str, Any], ...]], Any] = {}

    @functools.wraps(fn)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        # Convert kwargs to sorted tuple for consistent hashing
        # frozenset won't work for duplicate keys, tuple of tuples maintains order
        kwargs_key = tuple(sorted(kwargs.items()))

        # Handle unhashable args - convert to string repr as fallback
        hashable_args = []
        for arg in args:
            try:
                hash(arg)
                hashable_args.append(arg)
            except TypeError:
                # Fallback for unhashable types (list, dict, etc)
                hashable_args.append(repr(arg))

        # Same for kwargs values
        hashable_kwargs = []
        for k, v in kwargs_key:
            try:
                hash(v)
                hashable_kwargs.append((k, v))
            except TypeError:
                hashable_kwargs.append((k, repr(v)))

        cache_key = (tuple(hashable_args), tuple(hashable_kwargs))

        if cache_key in cache:
            return cache[cache_key]

        result = fn(*args, **kwargs)
        cache[cache_key] = result
        return result

    # Expose cache for introspection/testing
    wrapper.cache = cache
    wrapper.cache_clear = cache.clear
    wrapper.cache_info = lambda: f"hits={len(cache)}, size={len(cache)}"

    return wrapper

# More robust version handling edge cases:
def memoize_robust(fn: F) -> F:
    cache: Dict[Any, Any] = {}

    @functools.wraps(fn)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        # Create cache key - need to handle:
        # 1. Unhashable types in args/kwargs
        # 2. Mutable default arguments 
        # 3. Functions with *args, **kwargs

        def make_hashable(obj: Any) -> Any:
            if isinstance(obj, (list, set)):
                return tuple(make_hashable(item) for item in obj)
            elif isinstance(obj, dict):
                return tuple(sorted((k, make_hashable(v)) for k, v in obj.items()))
            elif hasattr(obj, '__dict__'):
                # Custom objects - use id() or repr()
                return (type(obj).__name__, id(obj))
            else:
                try:
                    hash(obj)
                    return obj
                except TypeError:
                    return repr(obj)

        # Build cache key
        args_key = tuple(make_hashable(arg) for arg in args)
        kwargs_key = tuple(sorted((k, make_hashable(v)) for k, v in kwargs.items()))
        cache_key = (args_key, kwargs_key)

        if cache_key not in cache:
            cache[cache_key] = fn(*args, **kwargs)

        return cache[cache_key]

    wrapper.cache = cache
    wrapper.cache_clear = cache.clear
    wrapper.cache_info = lambda: {"size": len(cache), "keys": list(cache.keys())}

    return wrapper

# Usage examples:
@memoize
def fibonacci(n: int) -> int:
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

@memoize
def expensive_func(x: int, y: str = "default", multiplier: float = 1.0) -> str:
    # Simulate expensive operation
    import time
    time.sleep(0.1)
    return f"{x * multiplier}_{y}"

# Test cases that break naive implementations:
@memoize_robust
def problematic_func(items: list, mapping: dict, flag: bool = True) -> int:
    return len(items) + len(mapping) + int(flag)

# Edge case: function that modifies mutable args (shouldn't affect cache)
@memoize
def mutating_func(data: list) -> int:
    # Don't actually mutate in memoized functions - undefined behavior
    return sum(data)

# Performance test harness:
def benchmark_memoization():
    import time

    # Without memoization
    def fib_naive(n):
        if n < 2: return n
        return fib_naive(n-1) + fib_naive(n-2)

    start = time.time()
    result1 = fib_naive(35)
    naive_time = time.time() - start

    # With memoization
    start = time.time() 
    result2 = fibonacci(35)
    memo_time = time.time() - start

    assert result1 == result2
    print(f"Naive: {naive_time:.3f}s, Memoized: {memo_time:.3f}s, Speedup: {naive_time/memo_time:.1f}x")
```

Key implementation details: cache key construction handles unhashable types via `repr()` fallback, kwargs normalization through sorted tuples, edge case handling for mutable objects. The `make_hashable` recursive function deals with nested collections. Performance characteristics: O(1) lookup after key construction, O(k) key construction where k is argument complexity. Memory grows unbounded - add LRU eviction for production use via `functools.lru_cache` or manual size limits.

```typescript
interface EventCallback {
  (...args: any[]): void;
}

class EventEmitter {
  private events: Map<string, Set<EventCallback>> = new Map();

  on(event: string, callback: EventCallback): void {
    // Handle case where event doesn't exist yet - Map.get() returns undefined
    if (!this.events.has(event)) {
      this.events.set(event, new Set());
    }
    // Set.add() handles duplicate callbacks automatically - no-op if exists
    this.events.get(event)!.add(callback);
  }

  emit(event: string, ...args: any[]): boolean {
    const callbacks = this.events.get(event);
    // Early return for non-existent events - no iteration overhead
    if (!callbacks || callbacks.size === 0) {
      return false;
    }

    // Iterator is stable even if callbacks modify the set during iteration
    for (const callback of callbacks) {
      try {
        // Apply args directly - no intermediate array creation
        callback(...args);
      } catch (error) {
        // Swallow individual callback errors to prevent cascade failures
        // Production code might want configurable error handling
        console.error(`Event callback error for '${event}':`, error);
      }
    }
    return true;
  }

  off(event: string, callback: EventCallback): boolean {
    const callbacks = this.events.get(event);
    if (!callbacks) {
      return false; // Event doesn't exist
    }

    const removed = callbacks.delete(callback);

    // Cleanup empty event entries to prevent memory leaks
    // Map iteration cost vs memory usage tradeoff
    if (callbacks.size === 0) {
      this.events.delete(event);
    }

    return removed;
  }

  // Utility for debugging/testing - returns copy to prevent external mutation
  listenerCount(event: string): number {
    return this.events.get(event)?.size ?? 0;
  }

  // Memory cleanup - removes all listeners for event or all events
  removeAllListeners(event?: string): void {
    if (event !== undefined) {
      this.events.delete(event);
    } else {
      this.events.clear();
    }
  }
}
```

Key implementation decisions:
- `Map<string, Set<EventCallback>>` for O(1) event lookup and O(1) callback add/remove
- Set automatically handles duplicate callback registration (idempotent)
- Iterator stability during emit() - callbacks can safely modify listener set
- Error isolation in emit() - one bad callback doesn't kill others
- Memory management - cleanup empty event entries in off()
- Type safety with interface constraint on callbacks

Edge cases handled:
- emit() on non-existent event returns false
- off() on non-existent event/callback returns false  
- Exception in callback doesn't break iteration
- Removing callback during emit() is safe due to Set iterator semantics

Complexity:
- on(): O(1) average case
- emit(): O(n) where n = callback count for event
- off(): O(1) average case

