use std::collections::HashMap;
use std::hash::Hash;
use std::time::{Duration, Instant};
use std::sync::{Arc, RwLock};

struct CacheEntry<V> {
    value: V,
    expires_at: Instant,
}

impl<V> CacheEntry<V> {
    fn new(value: V, ttl: Duration) -> Self {
        Self {
            value,
            expires_at: Instant::now() + ttl,
        }
    }

    fn is_expired(&self) -> bool {
        Instant::now() > self.expires_at
    }
}

pub struct TtlCache<K, V> {
    data: Arc<RwLock<HashMap<K, CacheEntry<V>>>>,
    default_ttl: Duration,
    // Optional: last cleanup to prevent excessive cleanup overhead
    last_cleanup: Arc<RwLock<Instant>>,
}

impl<K: Hash + Eq + Clone, V: Clone> TtlCache<K, V> {
    pub fn new(default_ttl: Duration) -> Self {
        Self {
            data: Arc::new(RwLock::new(HashMap::new())),
            default_ttl,
            last_cleanup: Arc::new(RwLock::new(Instant::now())),
        }
    }

    pub fn get(&self, key: &K) -> Option<V> {
        let data = self.data.read().unwrap();
        if let Some(entry) = data.get(key) {
            if !entry.is_expired() {
                return Some(entry.value.clone());
            }
        }
        None
    }

    pub fn insert(&self, key: K, value: V) {
        self.insert_with_ttl(key, value, self.default_ttl);
    }

    pub fn insert_with_ttl(&self, key: K, value: V, ttl: Duration) {
        let mut data = self.data.write().unwrap();
        data.insert(key, CacheEntry::new(value, ttl));

        // Opportunistic cleanup on write - prevents unbounded growth
        // Could also trigger on read count threshold or timer
        if data.len() % 100 == 0 {
            self.cleanup_expired_unlocked(&mut data);
        }
    }

    // Explicit cleanup - call periodically from background thread or timer
    pub fn cleanup_expired(&self) {
        let mut data = self.data.write().unwrap();
        self.cleanup_expired_unlocked(&mut data);
    }

    fn cleanup_expired_unlocked(&self, data: &mut HashMap<K, CacheEntry<V>>) {
        let now = Instant::now();
        data.retain(|_, entry| !entry.is_expired());
        *self.last_cleanup.write().unwrap() = now;
    }

    pub fn len(&self) -> usize {
        self.data.read().unwrap().len()
    }

    pub fn clear(&self) {
        self.data.write().unwrap().clear();
    }
}

// Background cleanup thread - spawn once per cache instance
impl<K: Hash + Eq + Clone + Send + 'static, V: Clone + Send + 'static> TtlCache<K, V> {
    pub fn spawn_cleanup_thread(cache: Arc<Self>, cleanup_interval: Duration) {
        tokio::spawn(async move {
            let mut interval = tokio::time::interval(cleanup_interval);
            loop {
                interval.tick().await;
                cache.cleanup_expired();
            }
        });
    }
}

// Example usage in long-running process:
/*
#[tokio::main] 
async fn main() {
    let cache: Arc<TtlCache<String, String>> = Arc::new(
        TtlCache::new(Duration::from_secs(300)) // 5 min default TTL
    );

    // Spawn background cleanup every 60 seconds
    TtlCache::spawn_cleanup_thread(
        Arc::clone(&cache), 
        Duration::from_secs(60)
    );

    // Your long-running process
    loop {
        let key = get_request_key();

        if let Some(cached) = cache.get(&key) {
            return_cached_response(cached);
        } else {
            let result = expensive_computation(&key);
            cache.insert(key, result.clone());
            return_response(result);
        }
    }
}
*/

// Alternative: LRU + TTL hybrid for bounded memory
use lru::LruCache;
use std::num::NonZeroUsize;

struct LruTtlCache<K, V> {
    data: Arc<RwLock<LruCache<K, CacheEntry<V>>>>,
    max_size: usize,
    default_ttl: Duration,
}

impl<K: Hash + Eq + Clone, V: Clone> LruTtlCache<K, V> {
    pub fn new(max_size: usize, default_ttl: Duration) -> Self {
        Self {
            data: Arc::new(RwLock::new(
                LruCache::new(NonZeroUsize::new(max_size).unwrap())
            )),
            max_size,
            default_ttl,
        }
    }

    pub fn get(&self, key: &K) -> Option<V> {
        let mut data = self.data.write().unwrap(); // write lock for LRU update
        if let Some(entry) = data.get(key) {
            if !entry.is_expired() {
                return Some(entry.value.clone());
            } else {
                // Remove expired entry immediately
                data.pop(key);
            }
        }
        None
    }

    pub fn insert(&self, key: K, value: V) {
        let mut data = self.data.write().unwrap();
        data.put(key, CacheEntry::new(value, self.default_ttl));
        // LRU handles size bounds, TTL handles staleness
    }
}
```

Key fixes:
1. `CacheEntry` wrapper with `expires_at` timestamp
2. `is_expired()` check on all reads - expired entries return None
3. Periodic cleanup via background thread prevents unbounded memory growth
4. Opportunistic cleanup on writes (every N insertions) 
5. LRU+TTL hybrid option for hard memory bounds

The cleanup thread is critical - without it, expired entries accumulate in the HashMap even though they're logically evicted. The `retain()` call actually frees the memory.

